{"file_path":"src/address.js","content":"/**
 * Cell address parsing and formatting. An address is one or two letters
 * naming a column (A..Z, then AA..ZZ) and one to three digits naming a row
 * of at least 1. Columns and rows are represented as 1-based integers.
 */

const MAX_COL = 702 // ZZ
const MAX_ROW = 999

/** Convert a 1-based column number to its letters (1 -> A, 27 -> AA, ...). */
export function colToLetters(col) {
  let n = col
  let out = ''
  while (n > 0) {
    const rem = (n - 1) % 26
    out = String.fromCharCode(65 + rem) + out
    n = Math.floor((n - 1) / 26)
  }
  return out
}

/** Convert column letters (A..ZZ) to a 1-based column number. */
export function lettersToCol(letters) {
  let n = 0
  for (const ch of letters) n = n * 26 + (ch.charCodeAt(0) - 64)
  return n
}

/**
 * Parse a token already known to be letters followed by digits (possibly
 * zero digits) into {col, row} if it names an addressable cell, or null if
 * it is outside the addressable range.
 */
export function parseLettersDigits(letters, digits) {
  if (letters.length < 1 || letters.length > 2) return null
  if (digits.length < 1 || digits.length > 3) return null
  const row = parseInt(digits, 10)
  if (row < 1 || row > MAX_ROW) return null
  const col = lettersToCol(letters)
  if (col < 1 || col > MAX_COL) return null
  return { col, row }
}

/** Split a token into its leading letters and trailing digits, or null. */
export function splitLettersDigits(token) {
  const m = /^([A-Za-z]+)([0-9]*)$/.exec(token)
  if (!m) return null
  return { letters: m[1], digits: m[2] }
}

/** Parse a full sheet-line address token (must be exactly letters+digits). */
export function parseSheetAddress(token) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(token)
  if (!m) return null
  return parseLettersDigits(m[1], m[2])
}

/** Canonical string form of a {col, row} coordinate. */
export function addressToString({ col, row }) {
  return colToLetters(col) + String(row)
}

/** Compare two {col, row} coordinates in column-major, then row order. */
export function compareCoords(a, b) {
  if (a.col !== b.col) return a.col - b.col
  return a.row - b.row
}
"}

