{"file_path":"src/lexer.js","content":"/**
 * Tokenizer for a formula body (the text after the leading `=`).
 */

const SYMBOLS = ['<=', '>=', '<>', '(', ')', ',', ':', '^', '*', '/', '+', '-', '<', '>', '=']

/** Tokenize a formula body. Throws on an unrecognized character. */
export function tokenize(text) {
  const tokens = []
  let i = 0
  while (i < text.length) {
    const ch = text[i]
    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }
    if (/[0-9]/.test(ch)) {
      const m = /^[0-9]+(\.[0-9]+)?/.exec(text.slice(i))
      tokens.push({ type: 'number', value: m[0] })
      i += m[0].length
      continue
    }
    if (/[A-Za-z]/.test(ch)) {
      const m = /^[A-Za-z]+[0-9]*/.exec(text.slice(i))
      tokens.push({ type: 'ident', value: m[0].toUpperCase() })
      i += m[0].length
      continue
    }
    const rest = text.slice(i)
    const sym = SYMBOLS.find((s) => rest.startsWith(s))
    if (sym) {
      tokens.push({ type: 'sym', value: sym })
      i += sym.length
      continue
    }
    throw new Error('lex')
  }
  return tokens
}
"}

