{"file_path":"src/parser.js","content":"/**
 * Recursive-descent parser for a formula body's token stream, producing an
 * AST. Ranges are only accepted directly as a call argument; everywhere
 * else `:` is simply not a valid continuation, so the grammar rejects it.
 */

import { tokenize } from './lexer.js'
import { splitLettersDigits } from './address.js'

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

class Cursor {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }
  peek(offset = 0) {
    return this.tokens[this.pos + offset]
  }
  next() {
    return this.tokens[this.pos++]
  }
  atEnd() {
    return this.pos >= this.tokens.length
  }
}

function fail() {
  throw new Error('parse')
}

function parseComparison(c) {
  let left = parseAdditive(c)
  while (!c.atEnd() && c.peek().type === 'sym' && COMPARISON_OPS.has(c.peek().value)) {
    const op = c.next().value
    const right = parseAdditive(c)
    left = { type: 'bin', op, left, right }
  }
  return left
}

function parseAdditive(c) {
  let left = parseMultiplicative(c)
  while (!c.atEnd() && c.peek().type === 'sym' && (c.peek().value === '+' || c.peek().value === '-')) {
    const op = c.next().value
    const right = parseMultiplicative(c)
    left = { type: 'bin', op, left, right }
  }
  return left
}

function parseMultiplicative(c) {
  let left = parsePower(c)
  while (!c.atEnd() && c.peek().type === 'sym' && (c.peek().value === '*' || c.peek().value === '/')) {
    const op = c.next().value
    const right = parsePower(c)
    left = { type: 'bin', op, left, right }
  }
  return left
}

function parsePower(c) {
  const left = parseUnary(c)
  if (!c.atEnd() && c.peek().type === 'sym' && c.peek().value === '^') {
    c.next()
    const right = parsePower(c)
    return { type: 'bin', op: '^', left, right }
  }
  return left
}

function parseUnary(c) {
  if (!c.atEnd() && c.peek().type === 'sym' && (c.peek().value === '-' || c.peek().value === '+')) {
    const op = c.next().value
    const arg = parseUnary(c)
    return { type: 'unary', op, arg }
  }
  return parseAtom(c)
}

function parseAtom(c) {
  if (c.atEnd()) fail()
  const tok = c.peek()
  if (tok.type === 'number') {
    c.next()
    return { type: 'num', value: parseFloat(tok.value) }
  }
  if (tok.type === 'sym' && tok.value === '(') {
    c.next()
    const inner = parseComparison(c)
    if (c.atEnd() || c.peek().type !== 'sym' || c.peek().value !== ')') fail()
    c.next()
    return inner
  }
  if (tok.type === 'ident') {
    c.next()
    if (!c.atEnd() && c.peek().type === 'sym' && c.peek().value === '(') {
      return parseCall(c, tok.value)
    }
    if (tok.value === 'TRUE') return { type: 'bool', value: true }
    if (tok.value === 'FALSE') return { type: 'bool', value: false }
    const split = splitLettersDigits(tok.value)
    return { type: 'ref', letters: split.letters, digits: split.digits }
  }
  fail()
}

function parseCall(c, name) {
  c.next() // '('
  const args = []
  if (!(c.peek() && c.peek().type === 'sym' && c.peek().value === ')')) {
    args.push(parseArgument(c))
    while (!c.atEnd() && c.peek().type === 'sym' && c.peek().value === ',') {
      c.next()
      args.push(parseArgument(c))
    }
  }
  if (c.atEnd() || c.peek().type !== 'sym' || c.peek().value !== ')') fail()
  c.next()
  return { type: 'call', name, args }
}

function parseArgument(c) {
  const a = c.peek(0)
  const b = c.peek(1)
  const d = c.peek(2)
  if (a && a.type === 'ident' && b && b.type === 'sym' && b.value === ':' && d && d.type === 'ident') {
    c.next()
    c.next()
    c.next()
    const from = splitLettersDigits(a.value)
    const to = splitLettersDigits(d.value)
    return { type: 'range', from, to }
  }
  return parseComparison(c)
}

/** Parse a formula body (without the leading `=`) into an AST, or null on grammar failure. */
export function parseFormula(text) {
  try {
    const tokens = tokenize(text)
    if (tokens.length === 0) return null
    const c = new Cursor(tokens)
    const ast = parseComparison(c)
    if (!c.atEnd()) return null
    return ast
  } catch {
    return null
  }
}
