{"file_path":"src/value.js","content":"/**
 * Runtime values: a number, text, a boolean, or an error token.
 */

export const num = (v) => ({ t: 'num', v })
export const text = (v) => ({ t: 'text', v })
export const bool = (v) => ({ t: 'bool', v })
export const err = (v) => ({ t: 'err', v })

export const isErr = (v) => v.t === 'err'

/** A number if finite, otherwise the division error (spec: any non-finite arithmetic result). */
export const finiteNum = (n) => (Number.isFinite(n) ? num(n) : err('#DIV/0!'))

/** Read a value in an arithmetic position: bool -> 1/0, text -> #VALUE!, error/num pass through. */
export function toNumber(v) {
  if (v.t === 'err') return v
  if (v.t === 'num') return v
  if (v.t === 'bool') return num(v.v ? 1 : 0)
  return err('#VALUE!')
}

function kindRank(v) {
  if (v.t === 'num') return 0
  if (v.t === 'text') return 1
  return 2 // bool
}

/** Compare two non-error values per the spec's cross-kind ordering. Returns -1, 0 or 1. */
export function compareValues(a, b) {
  const ra = kindRank(a)
  const rb = kindRank(b)
  if (ra !== rb) return ra < rb ? -1 : 1
  if (a.t === 'num') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  if (a.t === 'text') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  const av = a.v ? 1 : 0
  const bv = b.v ? 1 : 0
  return av - bv
}
"}

