 * {kind:'formula', ast} where ast is null when the grammar rejects the body.
 */
export function parseContent(raw) {
  if (raw.startsWith('=')) {
    return { kind: 'formula', ast: parseFormula(raw.slice(1)) }
  }
  return { kind: 'literal', value: parseLiteral(raw) }
}
