import { parseLettersDigits, addressToString, compareCoords } from './address.js'
import { num, bool, err, isErr, finiteNum, toNumber, compareValues } from './value.js'

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

const CALL_ARITY = {
  SUM: { min: 1, max: Infinity },
  MIN: { min: 1, max: Infinity },
  MAX: { min: 1, max: Infinity },
  COUNT: { min: 1, max: Infinity },
  AVG: { min: 1, max: Infinity },
  ABS: { min: 1, max: 1 },
  IF: { min: 3, max: 3 },
}

/**
 * Evaluates every declared cell against `sheet` (a Map of canonical address
 * to {ast|value, raw}), caching results and detecting cycles.
 */
export class Evaluator {
  constructor(sheet) {
    this.sheet = sheet
    this.cache = new Map()
    this.onStack = new Set()
  }

  cell(addr) {
    if (this.cache.has(addr)) return this.cache.get(addr)
    if (this.onStack.has(addr)) return err('#CYCLE!')
    const entry = this.sheet.get(addr)
    if (!entry) return num(0)
    this.onStack.add(addr)
    let result
    if (entry.content.kind === 'literal') {
      result = entry.content.value
    } else if (!entry.content.ast) {
      result = err('#ERR!')
    } else {
      result = this.evalNode(entry.content.ast)
    }
    this.onStack.delete(addr)
    this.cache.set(addr, result)
    return result
  }

  ref(node) {
    const coord = parseLettersDigits(node.letters, node.digits)
    if (!coord) return err('#REF!')
    return this.cell(addressToString(coord))
  }

  rangeCells(node) {
    const from = parseLettersDigits(node.from.letters, node.from.digits)
    const to = parseLettersDigits(node.to.letters, node.to.digits)
    if (!from || !to) return null
    const colMin = Math.min(from.col, to.col)
    const colMax = Math.max(from.col, to.col)
    const rowMin = Math.min(from.row, to.row)
    const rowMax = Math.max(from.row, to.row)
    const coords = []
    for (let col = colMin; col <= colMax; col++) {
      for (let row = rowMin; row <= rowMax; row++) coords.push({ col, row })
    }
    return coords
  }

  /** Evaluate an argument slot that must contribute a single scalar value. */
  evalScalarArg(node) {
    if (node.type === 'range') {
      const coords = this.rangeCells(node)
      if (!coords) return err('#REF!')
      if (coords.length !== 1) return err('#ERR!')
      return this.cell(addressToString(coords[0]))
    }
    return this.evalNode(node)
  }

  /** Flatten a variadic call's arguments left to right, expanding ranges. */
  collectArgValues(argNodes) {
    const flat = []
    for (const node of argNodes) {
      if (node.type === 'range') {
        const coords = this.rangeCells(node)
        if (!coords) {
          flat.push(err('#REF!'))
          continue
        }
        for (const coord of coords) flat.push(this.cell(addressToString(coord)))
      } else {
        flat.push(this.evalNode(node))
      }
    }
    return flat
  }

  evalNode(node) {
    switch (node.type) {
      case 'num':
        return num(node.value)
      case 'bool':
        return bool(node.value)
      case 'ref':
        return this.ref(node)
      case 'unary':
        return this.evalUnary(node)
      case 'bin':
        return this.evalBin(node)
      case 'call':
        return this.evalCall(node)
      default:
        throw new Error(`unreachable node type ${node.type}`)
    }
  }

  evalUnary(node) {
    const v = this.evalNode(node.arg)
    if (isErr(v)) return v
    const n = toNumber(v)
    if (isErr(n)) return n
    return finiteNum(node.op === '-' ? -n.v : n.v)
  }

  evalBin(node) {
    if (COMPARISON_OPS.has(node.op)) {
      const l = this.evalNode(node.left)
