 * Renders a runtime value as `values` mode prints it.
 */

function roundToSignificant(n, sig) {
  if (n === 0) return 0
  return Number(n.toPrecision(sig))
}

export function formatValue(v) {
  switch (v.t) {
    case 'num':
      return String(roundToSignificant(v.v, 10))
    case 'err':
      return v.v
    case 'bool':
      return v.v ? 'TRUE' : 'FALSE'
    case 'text':
      return v.v
    default:
      throw new Error(`unreachable value kind ${v.t}`)
  }
}
"}

