{"file_path":"src/sheet.js","content":"/**
 * Parses the sheet text format read from standard input.
 */

import { parseSheetAddress, addressToString } from './address.js'
import { parseContent } from './content.js'

export class SheetError extends Error {}

/**
 * Parse sheet text into a Map from canonical address to {content, line}.
 * Throws SheetError with a message matching the CLI's diagnostics on the
 * first invalid address or duplicate declaration.
 */
export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const sheet = new Map()
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const stripped = lines[i].replace(/^[ \t]+/, '')
    if (stripped === '' || stripped.startsWith('#')) continue

    const addrMatch = /^[^ \t]+/.exec(stripped)
    const addrToken = addrMatch[0]
    const rest = stripped.slice(addrToken.length)
    const content = rest.replace(/^[ \t]+/, '')

    const upper = addrToken.toUpperCase()
    const coord = parseSheetAddress(upper)
    if (!coord) throw new SheetError(`line ${lineNo}: invalid cell address ${upper}`)

    const canonical = addressToString(coord)
    if (sheet.has(canonical)) throw new SheetError(`line ${lineNo}: cell ${canonical} is declared twice`)

    sheet.set(canonical, { content: parseContent(content), line: lineNo })
  }
  return sheet
}
"}

