{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { parseSheet, SheetError } from './sheet.js'
import { Evaluator, collectDeps } from './evaluator.js'
import { formatValue } from './format.js'
import { addressToString, compareCoords, lettersToCol } from './address.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  const fs = require('node:fs')
  return fs.readFileSync(0, 'utf8')
}

async function main() {
  const mode = process.argv[2]
  if (mode !== 'values' && mode !== 'deps') {
    fail('usage: cli.js values|deps')
  }

  const chunks = []
  for await (const chunk of process.stdin) chunks.push(chunk)
  const input = chunks.join('')

  let sheet
  try {
    sheet = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) fail(e.message)
    throw e
  }

  const addresses = Array.from(sheet.keys())
  const coordOf = (addr) => {
    const m = /^([A-Za-z]+)([0-9]+)$/.exec(addr)
    return { col: lettersToCol(m[1]), row: parseInt(m[2], 10) }
  }
  addresses.sort((a, b) => compareCoords(coordOf(a), coordOf(b)))

  const out = []
  if (mode === 'values') {
    const evaluator = new Evaluator(sheet)
    for (const addr of addresses) {
      out.push(`${addr}=${formatValue(evaluator.cell(addr))}\n`)
    }
  } else {
    for (const addr of addresses) {
      const entry = sheet.get(addr)
      const deps = entry.content.kind === 'formula' && entry.content.ast ? collectDeps(entry.content.ast) : []
      const depNames = deps.map(addressToString).join(' ')
      out.push(depNames ? `${addr}: ${depNames}\n` : `${addr}:\n`)
    }
  }
  process.stdout.write(out.join(''))
  process.exit(0)
}

main()
"}

